export function joinGroundTruth(predictions=[],observations=[],{toleranceMs=15*60*1000}={}){const out=[];for(const p of predictions){const t=Date.parse(p.targetAt||'');if(!Number.isFinite(t)||!p.subjectId||!p.metric)continue;const candidates=observations.filter(o=>o.subjectId===p.subjectId&&o.metric===p.metric&&Number.isFinite(Date.parse(o.observedAt||''))).map(o=>({o,dt:Math.abs(Date.parse(o.observedAt)-t)})).filter(x=>x.dt<=toleranceMs).sort((a,b)=>a.dt-b.dt);if(candidates[0])out.push({prediction:p,observation:candidates[0].o,deltaMs:candidates[0].dt,error:Number(candidates[0].o.value)-Number(p.value)});}return out;}
